-- The rest of the 92 Swiss descriptions that were >=80% the old site's text,
-- rewritten from facts. Four agents re-opened every source before using a fact;
-- 318 of 348 cited quotes were found on their pages by script and the rest
-- checked by hand (PDFs, data feeds, map files). Reviewed and edited by hand.
-- Rules: PLAN.md, Next 0 — facts only, visitors only, no dates or years,
-- nothing the page already shows, every text its own.
--
-- 73 markets here. Held back, old text stays until Delfim decides:
-- brocante-de-rive-nyon, flohmi-spass-heimstrasse-bern, folie-flea-market-lausanne, slow-fashion-market-lausanne, vide-dressing-bains-payes-vevey
-- (no usable facts, or the market's existence is unconfirmed), plus the nine
-- doubtful listings, which were not drafted.
--
-- de/fr/it wait for a native speaker's pass, like every text on the site.

begin;

create temporary table new_description (slug text, locale text, value text) on commit drop;

do $$
declare n int;
begin
  update public.texts t
     set value = d.value, updated_at = now()
    from public.markets m, new_description d
   where t.entity_type = 'market' and t.entity_id = m.id and t.field = 'description'
     and m.slug = d.slug and t.locale = d.locale;
  get diagnostics n = row_count;
  if n <> 292 then raise exception 'expected 292 descriptions updated, got %', n; end if;

  update public.texts t
     set value = replace(t.value, b.old, b.new), updated_at = now()
    from public.markets m,
         (values ('en', $t$; January 2027 is the 27th edition.$t$, $t$.$t$),
                 ('de', $t$; im Januar 2027 zum 27. Mal.$t$, $t$.$t$),
                 ('fr', $t$ ; en janvier 2027, ce sera la 27e édition.$t$, $t$.$t$),
                 ('it', $t$; a gennaio 2027 si tiene la 27ª edizione.$t$, $t$.$t$)) as b(locale, old, new)
   where t.entity_type = 'market' and t.entity_id = m.id and t.field = 'description'
     and m.slug = 'brocante-de-la-gruyere-bulle' and t.locale = b.locale and position(b.old in t.value) > 0;
  get diagnostics n = row_count;
  if n <> 4 then raise exception 'Bulle: expected 4, got %', n; end if;
end $$;

commit;
